npm run start &
SERVER_PID=$!
sleep 2
node -e '
const http = require("http");

function fetchProduct(url) {
  return new Promise((resolve) => {
    const start = Date.now();
    console.log(`\n--- Request ${url} ---`);
    http.get(`http://localhost:3000${url}`, (res) => {
      console.log(`[${Date.now() - start}ms] Headers: ${res.statusCode}`);
      let body = "";
      res.on("data", (chunk) => {
        body += chunk.toString();
      });
      res.on("end", () => {
        console.log(`Has Brass lamp: ${body.includes("Brass lamp")}`);
        console.log(`Has EUR 110.40: ${body.includes("EUR 110.40")}`);
        console.log(`Has Stone vase: ${body.includes("Stone vase")}`);
        resolve();
      });
    });
  });
}

(async () => {
  await fetchProduct("/products/lamp?currency=EUR");
  await fetchProduct("/products/lamp?currency=EUR");
})();
'
sleep 2
kill $SERVER_PID
